    public List<Product> filterByCategory(String category) { return new ArrayList<>(); }
}

public class PricingEngine {
    public double getBasePrice(Product p) { return p.getPrice(); }
    public double applyMarkup(double price, double rate) { return price * (1 + rate); }
}

public class DiscountService {
    public double computeDiscount(Product p, String coupon) {
        if ("SAVE10".equals(coupon)) return p.getPrice() * 0.1;
        return 0.0;
    }
}

public class TaxCalculator {
    public double computeTax(double price, String region) {
        if ("EU".equals(region)) return price * 0.20;
        return price * 0.07;
    }
}

public class InventoryTracker {
    private Map<String, Integer> stock = new HashMap<>();
    public int getStock(String productId) { return stock.getOrDefault(productId, 0); }
    public void updateStock(String productId, int delta) {
        stock.merge(productId, delta, Integer::sum);
    }
}

public class CatalogExporter {
