import java.util.*;

public class ProductCatalog {
    private List<Product> products = new ArrayList<>();
    private Map<String, Integer> stockLevels = new HashMap<>();
    private Map<String, Double> discountCodes = new HashMap<>();
    private String defaultRegion = "US";
    private double markupRate = 0.15;

    // --- Search & Filter ---
    public List<Product> searchByName(String query) {
        List<Product> result = new ArrayList<>();
        for (Product p : products) {
            if (p.getName().toLowerCase().contains(query.toLowerCase())) result.add(p);
        }
        return result;
    }

    public List<Product> filterByCategory(String category) {
        List<Product> result = new ArrayList<>();
        for (Product p : products) {
            if (category.equals(p.getCategory())) result.add(p);
        }
        return result;
    }

    public List<Product> filterByPriceRange(double min, double max) {
        List<Product> result = new ArrayList<>();
        for (Product p : products) {
            if (p.getPrice() >= min && p.getPrice() <= max) result.add(p);
        }
        return result;
    }

    // --- Pricing ---
    public double getMarkedUpPrice(Product p) {
        return p.getPrice() * (1 + markupRate);
    }

    public double applyDiscount(Product p, String code) {
        double rate = discountCodes.getOrDefault(code, 0.0);
        return getMarkedUpPrice(p) * (1 - rate);
    }

    public void registerDiscountCode(String code, double rate) {
        if (rate < 0 || rate > 1) throw new IllegalArgumentException("Rate must be 0-1");
        discountCodes.put(code, rate);
    }

    // --- Tax ---
    public double computeTax(double price, String region) {
        switch (region) {
            case "EU": return price * 0.20;
            case "UK": return price * 0.20;
            case "CA": return price * 0.13;
            default:   return price * 0.07;
        }
    }

    public double getFinalPrice(Product p, String code, String region) {
        double discounted = applyDiscount(p, code);
        return discounted + computeTax(discounted, region);
    }

    // --- Inventory ---
    public int getStock(String productId) {
        return stockLevels.getOrDefault(productId, 0);
    }

    public void restock(String productId, int quantity) {
        if (quantity <= 0) throw new IllegalArgumentException("Quantity must be positive");
        stockLevels.merge(productId, quantity, Integer::sum);
    }

    public boolean reserveStock(String productId, int quantity) {
        int current = getStock(productId);
        if (current < quantity) return false;
        stockLevels.put(productId, current - quantity);
        return true;
    }

    public List<Product> getLowStockProducts(int threshold) {
        List<Product> result = new ArrayList<>();
        for (Product p : products) {
            if (getStock(p.getId()) < threshold) result.add(p);
        }
        return result;
    }

    // --- Export ---
    public String exportToCsv() {
        StringBuilder sb = new StringBuilder("id,name,category,price,stock\n");
        for (Product p : products) {
            sb.append(p.getId()).append(',').append(p.getName()).append(',')
              .append(p.getCategory()).append(',').append(p.getPrice()).append(',')
              .append(getStock(p.getId())).append('\n');
        }
        return sb.toString();
    }

    public String exportToJson() {
        StringBuilder sb = new StringBuilder("[\n");
        for (int i = 0; i < products.size(); i++) {
            Product p = products.get(i);
            sb.append("  {\"id\":\"").append(p.getId())
              .append("\",\"name\":\"").append(p.getName())
              .append("\",\"price\":").append(p.getPrice())
              .append(",\"stock\":").append(getStock(p.getId())).append("}");
            if (i < products.size() - 1) sb.append(',');
            sb.append('\n');
        }
        sb.append(']');
        return sb.toString();
    }

    // --- Product Management ---
    public void addProduct(Product p) {
        products.add(p);
        stockLevels.putIfAbsent(p.getId(), 0);
    }

    public boolean removeProduct(String productId) {
        boolean removed = products.removeIf(p -> p.getId().equals(productId));
        if (removed) stockLevels.remove(productId);
        return removed;
    }

    public Optional<Product> findById(String productId) {
        return products.stream().filter(p -> p.getId().equals(productId)).findFirst();
    }

    public int getTotalProductCount() { return products.size(); }
    public double getTotalInventoryValue() {
        double total = 0;
        for (Product p : products) total += p.getPrice() * getStock(p.getId());
        return total;
    }

    // Inner stub
    public static class Product {
        private String id, name, category;
        private double price;
        public Product(String id, String name, String category, double price) {
            this.id = id; this.name = name; this.category = category; this.price = price;
        }
        public String getId() { return id; }
        public String getName() { return name; }
        public String getCategory() { return category; }
        public double getPrice() { return price; }
    }
}

