        assertEquals(1, c.searchByName("apple").size());
        assertEquals(2, c.filterByCategory("fruit").size());
        assertEquals(2, c.filterByPriceRange(1.5, 20.0).size());
    }

    @Test
    public void pricingDiscountAndTax() {
        ProductCatalog c = catalog();
        ProductCatalog.Product hammer = c.findById("3").get();
        assertEquals(17.25, c.getMarkedUpPrice(hammer), 1e-9);
        c.registerDiscountCode("TEN", 0.1);
        assertEquals(15.525, c.applyDiscount(hammer, "TEN"), 1e-9);
        assertEquals(17.25, c.applyDiscount(hammer, "NONE"), 1e-9);
        assertEquals(18.63, c.getFinalPrice(hammer, "TEN", "EU"), 1e-9);
        assertEquals(13.0, c.computeTax(100.0, "CA"), 1e-9);
        assertEquals(7.0, c.computeTax(100.0, "XX"), 1e-9);
    }

    @Test(expected = IllegalArgumentException.class)
    public void discountRateMustBeAFraction() {
        new ProductCatalog().registerDiscountCode("BAD", 1.5);
    }

    @Test
    public void inventory() {
        ProductCatalog c = catalog();
        c.restock("1", 5);
        assertTrue(c.reserveStock("1", 3));
        assertEquals(2, c.getStock("1"));
        assertFalse(c.reserveStock("1", 3));
        assertEquals(2, c.getLowStockProducts(1).size());
