import java.util.*;
import java.util.concurrent.*;
import java.util.function.*;

public class EventBus {
    private final Map<String, List<Object>> subscribers = new ConcurrentHashMap<>();
    private final BlockingQueue<Object[]> asyncQueue = new LinkedBlockingQueue<>(1000);
    private final Map<String, Long> eventCounts = new ConcurrentHashMap<>();
    private final Map<String, Long> errorCounts = new ConcurrentHashMap<>();
    private final List<Object[]> deadLetters = new ArrayList<>();
    private final Map<String, Predicate<Object>> filters = new HashMap<>();
    private volatile boolean running = false;
    private Thread dispatchThread;

    // --- Registration ---
    public void subscribe(String eventType, Object handler) {
        subscribers.computeIfAbsent(eventType, k -> new CopyOnWriteArrayList<>()).add(handler);
    }

    public void unsubscribe(String eventType, Object handler) {
        List<Object> list = subscribers.get(eventType);
        if (list != null) list.remove(handler);
    }

    public void unsubscribeAll(String eventType) {
        subscribers.remove(eventType);
    }

    public int getSubscriberCount(String eventType) {
        return subscribers.getOrDefault(eventType, Collections.emptyList()).size();
    }

    // --- Filtering ---
    public void addFilter(String eventType, Predicate<Object> filter) {
        filters.put(eventType, filter);
    }

    public void removeFilter(String eventType) {
        filters.remove(eventType);
    }

    private boolean passesFilter(String eventType, Object event) {
        Predicate<Object> f = filters.get(eventType);
        return f == null || f.test(event);
    }

    // --- Dispatch ---
    public void publish(String eventType, Object event) {
        if (!passesFilter(eventType, event)) return;
        eventCounts.merge(eventType, 1L, Long::sum);
        List<Object> handlers = subscribers.getOrDefault(eventType, Collections.emptyList());
        if (handlers.isEmpty()) {
            deadLetters.add(new Object[]{eventType, event});
            return;
        }
        for (Object h : handlers) {
            try {
                dispatchToHandler(h, event);
            } catch (Exception e) {
                errorCounts.merge(eventType, 1L, Long::sum);
            }
        }
    }

    private void dispatchToHandler(Object handler, Object event) {
        System.out.println("Dispatch: " + handler + " <- " + event);
    }

    // --- Async ---
    public void publishAsync(String eventType, Object event) {
        asyncQueue.offer(new Object[]{eventType, event});
    }

    public void startAsync() {
        running = true;
        dispatchThread = new Thread(() -> {
            while (running) {
                try {
                    Object[] item = asyncQueue.poll(100, TimeUnit.MILLISECONDS);
                    if (item != null) publish((String) item[0], item[1]);
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                    break;
                }
            }
        });
        dispatchThread.setDaemon(true);
        dispatchThread.start();
    }

    public void stopAsync() {
        running = false;
        if (dispatchThread != null) dispatchThread.interrupt();
    }

    public int getQueueSize() { return asyncQueue.size(); }

    // --- Dead Letters ---
    public List<Object[]> getDeadLetters() { return Collections.unmodifiableList(deadLetters); }
    public void clearDeadLetters() { deadLetters.clear(); }
    public void retryDeadLetters() {
        List<Object[]> copy = new ArrayList<>(deadLetters);
        deadLetters.clear();
        for (Object[] item : copy) publish((String) item[0], item[1]);
    }

    // --- Metrics ---
    public long getEventCount(String eventType) {
        return eventCounts.getOrDefault(eventType, 0L);
    }
    public long getErrorCount(String eventType) {
        return errorCounts.getOrDefault(eventType, 0L);
    }
    public Map<String, Long> getAllEventCounts() {
        return Collections.unmodifiableMap(eventCounts);
    }
    public void resetMetrics() {
        eventCounts.clear();
        errorCounts.clear();
    }

    public Map<String, Integer> getSubscriberCounts() {
        Map<String, Integer> result = new HashMap<>();
        for (var e : subscribers.entrySet()) result.put(e.getKey(), e.getValue().size());
        return result;
    }
}

