import java.util.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class EventBusRefactorTest {
    @Test
    public void subscriptions() {
        EventBus bus = new EventBus();
        Object h1 = "h1", h2 = "h2";
        bus.subscribe("a", h1);
        bus.subscribe("a", h2);
        assertEquals(2, bus.getSubscriberCount("a"));
        assertEquals(Integer.valueOf(2), bus.getSubscriberCounts().get("a"));
        bus.unsubscribe("a", h1);
        assertEquals(1, bus.getSubscriberCount("a"));
        bus.unsubscribeAll("a");
        assertEquals(0, bus.getSubscriberCount("a"));
    }

    @Test
    public void unhandledEventsBecomeDeadLetters() {
        EventBus bus = new EventBus();
        bus.publish("x", "e1");
        assertEquals(1, bus.getDeadLetters().size());
        assertEquals(1L, bus.getEventCount("x"));
        bus.subscribe("x", "handler");
        bus.retryDeadLetters();
        assertEquals(0, bus.getDeadLetters().size());
        assertEquals(2L, bus.getEventCount("x"));
        assertEquals(0L, bus.getErrorCount("x"));
    }

    @Test
    public void filtersDropEventsBeforeCounting() {
        EventBus bus = new EventBus();
        bus.subscribe("a", "handler");
        bus.addFilter("a", e -> !"skip".equals(e));
        bus.publish("a", "skip");
        assertEquals(0L, bus.getEventCount("a"));
        bus.publish("a", "ok");
        assertEquals(1L, bus.getEventCount("a"));
        bus.removeFilter("a");
        bus.publish("a", "skip");
        assertEquals(2L, bus.getEventCount("a"));
    }

    @Test
    public void metricsResetAndAsyncQueue() {
        EventBus bus = new EventBus();
        bus.publish("x", "e");
        bus.resetMetrics();
        assertEquals(0L, bus.getEventCount("x"));
        assertTrue(bus.getAllEventCounts().isEmpty());
        bus.publishAsync("y", "e");
        assertEquals(1, bus.getQueueSize());
        bus.clearDeadLetters();
        assertTrue(bus.getDeadLetters().isEmpty());
    }
}

