import java.util.*;
import java.io.*;
import java.util.zip.*;

public class FileProcessor {
    private int processedCount = 0;
    private int failedCount = 0;
    private int skippedCount = 0;
    private List<String> errorLog = new ArrayList<>();
    private Map<String, String> config = new HashMap<>();

    // --- Reading ---
    public List<String> readFile(String path) throws IOException {
        List<String> lines = new ArrayList<>();
        try (BufferedReader br = new BufferedReader(new FileReader(path))) {
            String line;
            while ((line = br.readLine()) != null) lines.add(line);
        }
        return lines;
    }

    public byte[] readBinary(String path) throws IOException {
        return java.nio.file.Files.readAllBytes(java.nio.file.Paths.get(path));
    }

    // --- Validation ---
    public boolean validateNotEmpty(List<String> lines) {
        return lines != null && !lines.isEmpty();
    }

    public boolean validateLineCount(List<String> lines, int min, int max) {
        return lines.size() >= min && lines.size() <= max;
    }

    public boolean validateHeader(List<String> lines, String expectedHeader) {
        return !lines.isEmpty() && lines.get(0).equals(expectedHeader);
    }

    // --- Parsing ---
    public List<String[]> parseCsv(List<String> lines) {
        List<String[]> result = new ArrayList<>();
        for (String line : lines) result.add(line.split(",", -1));
        return result;
    }

    public Map<String, String> parseKeyValue(List<String> lines) {
        Map<String, String> map = new HashMap<>();
        for (String line : lines) {
            int eq = line.indexOf('=');
            if (eq >= 0) map.put(line.substring(0, eq).trim(), line.substring(eq + 1).trim());
        }
        return map;
    }

    public List<Map<String, String>> parseCsvWithHeader(List<String> lines) {
        if (lines.size() < 2) return Collections.emptyList();
        String[] headers = lines.get(0).split(",", -1);
        List<Map<String, String>> result = new ArrayList<>();
        for (int i = 1; i < lines.size(); i++) {
            String[] vals = lines.get(i).split(",", -1);
            Map<String, String> row = new LinkedHashMap<>();
            for (int j = 0; j < headers.length && j < vals.length; j++) {
                row.put(headers[j].trim(), vals[j].trim());
            }
            result.add(row);
        }
        return result;
    }

    // --- Transformation ---
    public String transformToUpperCase(String value) { return value.toUpperCase(); }
    public String trimAndNormalize(String value) { return value.trim().replaceAll("\\s+", " "); }
    public double parseDouble(String value) { return Double.parseDouble(value.trim()); }
    public int parseInt(String value) { return Integer.parseInt(value.trim()); }

    public List<Map<String, String>> applyTransformations(List<Map<String, String>> rows) {
        List<Map<String, String>> result = new ArrayList<>();
        for (Map<String, String> row : rows) {
            Map<String, String> transformed = new LinkedHashMap<>();
            for (var e : row.entrySet()) transformed.put(e.getKey(), trimAndNormalize(e.getValue()));
            result.add(transformed);
        }
        return result;
    }

    // --- Business Rules ---
    public boolean applyAgeRule(Map<String, String> row) {
        try { return parseInt(row.getOrDefault("age", "0")) >= 18; }
        catch (NumberFormatException e) { return false; }
    }

    public boolean applyAmountRule(Map<String, String> row) {
        try { return parseDouble(row.getOrDefault("amount", "0")) > 0; }
        catch (NumberFormatException e) { return false; }
    }

    // --- Writing ---
    public void writeFile(String path, List<String> lines) throws IOException {
        try (BufferedWriter bw = new BufferedWriter(new java.io.FileWriter(path))) {
            for (String line : lines) { bw.write(line); bw.newLine(); }
        }
    }

    public void writeCsv(String path, List<Map<String, String>> rows) throws IOException {
        if (rows.isEmpty()) return;
        List<String> lines = new ArrayList<>();
        lines.add(String.join(",", rows.get(0).keySet()));
        for (Map<String, String> row : rows) lines.add(String.join(",", row.values()));
        writeFile(path, lines);
    }

    // --- Compression ---
    public void compress(String inputPath, String outputPath) throws IOException {
        try (GZIPOutputStream gzip = new GZIPOutputStream(new FileOutputStream(outputPath));
             FileInputStream fis = new FileInputStream(inputPath)) {
            byte[] buf = new byte[1024];
            int len;
            while ((len = fis.read(buf)) != -1) gzip.write(buf, 0, len);
        }
    }

    // --- Stats ---
    public void recordSuccess() { processedCount++; }
    public void recordFailure(String msg) { failedCount++; errorLog.add(msg); }
    public void recordSkipped() { skippedCount++; }
    public int getProcessedCount() { return processedCount; }
    public int getFailedCount() { return failedCount; }
    public int getSkippedCount() { return skippedCount; }
    public List<String> getErrorLog() { return Collections.unmodifiableList(errorLog); }
    public void resetStats() { processedCount = 0; failedCount = 0; skippedCount = 0; errorLog.clear(); }

    public Map<String, Integer> getSummary() {
        Map<String, Integer> s = new LinkedHashMap<>();
        s.put("processed", processedCount);
        s.put("failed", failedCount);
        s.put("skipped", skippedCount);
        return s;
    }
}

