import java.io.File;
import java.util.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class FileProcessorRefactorTest {
    private final FileProcessor fp = new FileProcessor();

    @Test
    public void validation() {
        assertFalse(fp.validateNotEmpty(null));
        assertFalse(fp.validateNotEmpty(new ArrayList<String>()));
        assertTrue(fp.validateNotEmpty(Arrays.asList("a")));
        assertTrue(fp.validateLineCount(Arrays.asList("a", "b"), 1, 2));
        assertFalse(fp.validateLineCount(Arrays.asList("a", "b"), 3, 5));
        assertTrue(fp.validateHeader(Arrays.asList("id,name"), "id,name"));
        assertFalse(fp.validateHeader(new ArrayList<String>(), "id,name"));
    }

    @Test
    public void parsing() {
        assertEquals(3, fp.parseCsv(Arrays.asList("a,b,", "c")).get(0).length);
        Map<String, String> kv = fp.parseKeyValue(Arrays.asList(" k = v ", "noeq", "x=1=2"));
        assertEquals(2, kv.size());
        assertEquals("v", kv.get("k"));
        assertEquals("1=2", kv.get("x"));
        List<Map<String, String>> rows =
            fp.parseCsvWithHeader(Arrays.asList("name, age", "ann, 30", "bob"));
        assertEquals(2, rows.size());
        assertEquals("30", rows.get(0).get("age"));
        assertEquals(1, rows.get(1).size());
        assertTrue(fp.parseCsvWithHeader(Arrays.asList("only header")).isEmpty());
    }

    @Test
    public void transformationsAndRules() {
        assertEquals("a b", fp.trimAndNormalize("  a   b "));
        assertEquals(42, fp.parseInt(" 42 "));
        assertEquals("ABC", fp.transformToUpperCase("abc"));
        Map<String, String> row = new LinkedHashMap<>();
        row.put("name", "  x   y ");
        assertEquals("x y", fp.applyTransformations(Arrays.asList(row)).get(0).get("name"));
        assertTrue(fp.applyAgeRule(Collections.singletonMap("age", "18")));
        assertFalse(fp.applyAgeRule(Collections.singletonMap("age", "17")));
        assertFalse(fp.applyAgeRule(Collections.singletonMap("age", "x")));
        assertTrue(fp.applyAmountRule(Collections.singletonMap("amount", "0.01")));
        assertFalse(fp.applyAmountRule(new HashMap<String, String>()));
    }

    @Test
    public void statistics() {
        fp.recordSuccess();
        fp.recordSuccess();
        fp.recordFailure("bad row");
        fp.recordSkipped();
        Map<String, Integer> expected = new LinkedHashMap<>();
        expected.put("processed", 2);
