}

public class ExpiryPolicy {
    private long ttlMs;
    public ExpiryPolicy(long ttlMs) { this.ttlMs = ttlMs; }
    public boolean isExpired(long createdAt) { return System.currentTimeMillis() - createdAt > ttlMs; }
}

public class PermissionChecker {
    public boolean hasPermission(String role, String resource) {
        if ("admin".equals(role)) return true;
        if ("user".equals(role)) return !resource.startsWith("/admin");
        return false;
    }
}

public class RateLimiter {
    private Map<String, Integer> counts = new HashMap<>();
    private int maxPerMinute;
    public RateLimiter(int maxPerMinute) { this.maxPerMinute = maxPerMinute; }
    public boolean allow(String sessionId) {
        int c = counts.merge(sessionId, 1, Integer::sum);
        return c <= maxPerMinute;
    }
}

public class AuditLogger {
    private List<String> log = new ArrayList<>();
