import java.util.*;

public class SessionManager {
    private final Map<String, Session> sessions = new HashMap<>();
    private final Map<String, Integer> rateCounts = new HashMap<>();
    private final List<String> auditLog = new ArrayList<>();
    private long sessionTtlMs = 30 * 60 * 1000L; // 30 min
    private int maxRequestsPerMinute = 60;

    // --- Session CRUD ---
    public String createSession(String userId, String role) {
        String token = generateToken(userId);
        sessions.put(token, new Session(token, userId, role, System.currentTimeMillis()));
        audit("CREATE session for " + userId);
        return token;
    }

    public boolean invalidate(String token) {
        Session s = sessions.remove(token);
        if (s != null) { audit("INVALIDATE " + token); return true; }
        return false;
    }

    public Optional<Session> getSession(String token) {
        Session s = sessions.get(token);
        if (s == null) return Optional.empty();
        if (isExpired(s)) { sessions.remove(token); audit("EXPIRED " + token); return Optional.empty(); }
        return Optional.of(s);
    }

    public void purgeExpired() {
        sessions.entrySet().removeIf(e -> isExpired(e.getValue()));
    }

    public int getActiveSessionCount() { return sessions.size(); }

    // --- Token ---
    private String generateToken(String userId) {
        return "sess-" + userId.hashCode() + "-" + System.currentTimeMillis();
    }

    public boolean isValidToken(String token) {
        return getSession(token).isPresent();
    }

    // --- Expiry ---
    private boolean isExpired(Session s) {
        return System.currentTimeMillis() - s.createdAt > sessionTtlMs;
    }

    public void setTtl(long ttlMs) { this.sessionTtlMs = ttlMs; }
    public long getTtl() { return sessionTtlMs; }

    // --- Permissions ---
    public boolean hasPermission(String token, String resource) {
        return getSession(token).map(s -> checkPermission(s.role, resource)).orElse(false);
    }

    private boolean checkPermission(String role, String resource) {
        if ("admin".equals(role)) return true;
        if ("user".equals(role)) return !resource.startsWith("/admin");
        return false;
    }

    // --- Rate Limiting ---
    public boolean allowRequest(String token) {
        int count = rateCounts.merge(token, 1, Integer::sum);
        return count <= maxRequestsPerMinute;
    }

    public void resetRateLimits() { rateCounts.clear(); }
    public int getRequestCount(String token) { return rateCounts.getOrDefault(token, 0); }

    // --- Audit ---
    private void audit(String event) {
        auditLog.add(System.currentTimeMillis() + ": " + event);
    }

    public List<String> getAuditLog() { return Collections.unmodifiableList(auditLog); }
    public void clearAuditLog() { auditLog.clear(); }

    // --- Serialization ---
    public String serializeSession(String token) {
        return getSession(token)
            .map(s -> s.token + "|" + s.userId + "|" + s.role + "|" + s.createdAt)
            .orElse("");
    }

    public Session deserializeSession(String serialized) {
        String[] parts = serialized.split("\\|");
        if (parts.length != 4) throw new IllegalArgumentException("Invalid format");
        return new Session(parts[0], parts[1], parts[2], Long.parseLong(parts[3]));
    }

    // Session DTO
    public static class Session {
        final String token, userId, role;
        final long createdAt;
        Session(String token, String userId, String role, long createdAt) {
            this.token = token; this.userId = userId;
            this.role = role; this.createdAt = createdAt;
        }
    }
}

