import org.junit.Test;
import static org.junit.Assert.*;

public class SessionManagerRefactorTest {
    @Test
    public void sessionLifecycle() {
        SessionManager m = new SessionManager();
        String token = m.createSession("ann", "user");
        assertTrue(token, token.startsWith("sess-"));
        assertEquals(1, m.getActiveSessionCount());
        assertTrue(m.isValidToken(token));
        assertTrue(m.invalidate(token));
        assertFalse(m.invalidate(token));
        assertFalse(m.isValidToken(token));
    }

    @Test
    public void permissionsFollowTheRole() {
        SessionManager m = new SessionManager();
        String admin = m.createSession("root", "admin");
        String user = m.createSession("ann", "user");
        String guest = m.createSession("gus", "guest");
        assertTrue(m.hasPermission(admin, "/admin/x"));
        assertFalse(m.hasPermission(user, "/admin/x"));
        assertTrue(m.hasPermission(user, "/home"));
        assertFalse(m.hasPermission(guest, "/home"));
        assertFalse(m.hasPermission("no-such-token", "/home"));
    }

    @Test
    public void expiredSessionsAreDropped() {
        SessionManager m = new SessionManager();
        String token = m.createSession("ann", "user");
        m.setTtl(-1);
        assertEquals(-1L, m.getTtl());
        assertFalse(m.getSession(token).isPresent());
        assertEquals(0, m.getActiveSessionCount());
    }

    @Test
    public void rateLimiting() {
        SessionManager m = new SessionManager();
        for (int i = 0; i < 60; i++) assertTrue(m.allowRequest("t"));
        assertFalse(m.allowRequest("t"));
        assertEquals(61, m.getRequestCount("t"));
        m.resetRateLimits();
        assertEquals(0, m.getRequestCount("t"));
    }

    @Test
    public void serialisationAndAudit() {
        SessionManager m = new SessionManager();
        String token = m.createSession("ann", "user");
        String[] parts = m.serializeSession(token).split("\\|");
        assertEquals(4, parts.length);
        assertEquals(token, parts[0]);
        assertEquals("ann", parts[1]);
        assertEquals("user", parts[2]);
        assertNotNull(m.deserializeSession("t|u|r|5"));
        assertEquals("", m.serializeSession("no-such-token"));
        m.invalidate(token);
        assertEquals(2, m.getAuditLog().size());
        assertTrue(m.getAuditLog().get(0).contains("CREATE session for ann"));
        m.clearAuditLog();
        assertTrue(m.getAuditLog().isEmpty());
    }

    @Test(expected = IllegalArgumentException.class)
    public void malformedSerialisationIsRejected() {
        new SessionManager().deserializeSession("a|b");
    }
}
